/*
 * A082507  Generated by a 3rd-order formal recursion with suitable initial
 *          values as follows: a(n) = n - a(n-1) - a(n-2) - a(n-3);
 *          a(0)=a(1)=a(2)=0.
 * https://oeis.org/A082507
 *
 * Offset:    -1    (a(-1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = n - a(n-1) - a(n-2) - a(n-3); Initial values: a(-1)=2,
 *            a(0)=a(1)=a(2)=0
 * Range:     u8 n <= 1014, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static seq_t *cache = NULL;      /* stores a(n) with index = n + 1 */
static idx_t cache_size = 0;     /* number of elements currently stored */

/* Initialise cache with the first four known terms:
   cache[0] = a(-1), cache[1] = a(0), cache[2] = a(1), cache[3] = a(2) */
static void init_cache(void)
{
    if (cache)
        return;
    cache = (seq_t *)calloc(4, sizeof(seq_t));
    if (!cache)
        abort();                  /* allocation error */
    cache_size = 4;
    cache[0] = (seq_t)2;          /* a(-1) */
    /* a(0), a(1), a(2) are already zero */
}

/* Extend the cached values up to n (inclusive).  The array index for a(n)
   is n + 1 because the offset is -1. */
static void extend_cache(idx_t n)
{
    idx_t target_index = n + 1;    /* index of a(n) in the array */
    if (target_index < cache_size)
        return;                    /* already computed */

    /* Allocate larger array */
    idx_t new_size = target_index + 1;
    seq_t *new_cache = (seq_t *)realloc(cache, new_size * sizeof(seq_t));
    if (!new_cache)
        abort();                  /* allocation error */
    cache = new_cache;

    /* Compute new entries sequentially */
    for (idx_t i = cache_size; i <= target_index; ++i) {
        /* i corresponds to n = i - 1 */
        idx_t cur_n = i - 1;
        /* Use seq_t arithmetic (works for native and arbitrary‑precision types) */
        seq_t val = (seq_t)cur_n
                    - cache[i - 1]   /* a(n-1) */
                    - cache[i - 2]   /* a(n-2) */
                    - cache[i - 3];  /* a(n-3) */
        cache[i] = val;
    }
    cache_size = new_size;
}

/* Retrieve a(n) for any n >= -1.  For n < -1 the function returns 0. */
seq_t a(idx_t n)
{
    if (n < -1)
        return (seq_t)0;          /* undefined region */
    init_cache();
    extend_cache(n);
    return cache[n + 1];
}
